  {
    "id": "act_fixture",
    "name": "update-ticket-priority",
    "description": "Change a support ticket priority.",
    "method": "PATCH",
    "urlTemplate": "https://support.example.com/tickets/{{input.ticketId}}",
    "headers": {
      "Authorization": "Bearer {{secret:SUPPORT_KEY}}"
    },
    "bodyTemplate": {
      "priority": "{{input.priority}}"
    },
    "inputSchema": {
      "type": "object",
      "properties": {
        "ticketId": {
          "type": "string"
        },
        "priority": {
          "type": "string",
          "enum": [
            "low",
            "high"
          ]
        }
      },
      "required": [
        "ticketId",
        "priority"
      ]
    },
    "requiresApproval": true,
    "enabled": true,
    "secrets": [
      "SUPPORT_KEY"
    ],
    "currentVersionId": "acv_fixture",
