    "urlTemplate": "https://mail.example.com/emails",
    "headers": {
      "Authorization": "Bearer {{secret:MAIL_KEY}}"
    },
    "bodyTemplate": {
      "to": "{{input.to}}"
    },
    "inputSchema": {
      "type": "object",
      "properties": {
        "to": {
